#define MAX_SVG_BYTES       (1024L * 1024L)

enum { ID_BACK = 101, ID_FWD, ID_STOP, ID_RELOAD, ID_HOME, ID_GO, ID_ADDR, ID_VIEW, ID_BOOKMARK };
#define ID_CTRL_BASE        1000
