/* 一番外のウィンドウ (フレームでなければ自分) */
static HWND TopMain(void)
{
    HWND w = g_hwndMain, p;
    while ((p = GetParent(w)) != NULL) {
        w = p;
    }
    return w;
}

/* 表示ウィンドウにキー入力を移す。フレームは、利用者がそのフレームを操作中のときだけ (読み込むたびに奪わない) */
static void FocusView(void)
{
    HWND f = GetFocus();
    if (g_frameHost != NULL && f != g_hwndMain && !IsChild(g_hwndMain, f)) {
        return;
    }
    if (f != NULL && IsChild(g_hwndView, f)) {
        return;                         /* ページの部品にある (focus() や autofocus で移した) */
    }
    SetFocus(g_hwndView);
}

