/* ---------------------------------------------------------------- 汎用 */

static void OutOfMemory(void)
{
    MessageBox(NULL, "メモリが不足しています。", APP_NAME, MB_OK | MB_ICONSTOP);
    ExitProcess(1);
}

static void *xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (p == NULL) {
        OutOfMemory();
    }
    return p;
}

static void *xrealloc(void *p, size_t n)
{
    p = realloc(p, n ? n : 1);
    if (p == NULL) {
        OutOfMemory();
    }
    return p;
}

/* css.c が使うメモリ確保 (失敗したら終了する) */
void *CssXmalloc(size_t n)
{
    return xmalloc(n);
}

void *CssXrealloc(void *p, size_t n)
{
    return xrealloc(p, n);
}

static char *xstrdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char  *d = xmalloc(n);
    memcpy(d, s, n);
    return d;
}

/* strncpy と違い残りを 0 で埋めないので、size を超えて書くことはない */
static void StrCopy(char *dst, const char *src, int size)
{
    int n;
    if (size <= 0) {
        return;
    }
    n = (int)strlen(src);
    if (n > size - 1) {
        n = size - 1;
    }
    memmove(dst, src, n);
    dst[n] = '\0';
}

static void StrCat(char *dst, const char *src, int size)
{
    int n = (int)strlen(dst);
    if (n < size - 1) {
        StrCopy(dst + n, src, size - n);
    }
}

static void *GrowArray(void *p, int *cap, int need, int elem)
{
    if (need > *cap) {
        int nc = *cap ? *cap * 2 : 32;
        while (nc < need) {
            nc *= 2;
        }
        p = xrealloc(p, (size_t)nc * elem);
        *cap = nc;
    }
    return p;
}

#define GROW(arr, n, cap)   ((arr) = GrowArray((arr), &(cap), (n) + 1, sizeof(*(arr))))

static void SbAddN(StrBuf *sb, const char *s, int n)
{
    sb->p = GrowArray(sb->p, &sb->cap, sb->len + n + 1, 1);
    if (n > 0) {
        memcpy(sb->p + sb->len, s, n);
    }
    sb->len += n;
    sb->p[sb->len] = '\0';
}

static void SbAdd(StrBuf *sb, const char *s)
{
    SbAddN(sb, s, (int)strlen(s));
}

static void SbAddC(StrBuf *sb, int c)
{
    char ch = (char)c;
    SbAddN(sb, &ch, 1);
}

static const char *SbStr(const StrBuf *sb)
{
    return sb->p ? sb->p : "";
}

/* "a|b|c" の中に name があるか */
static int Is(const char *name, const char *list)
{
    const char *p = list, *q;

    for (;;) {
        for (q = name; *q != '\0' && *q == *p && *p != '|'; q++, p++) {
        }
        if (*q == '\0' && (*p == '|' || *p == '\0')) {
            return 1;
        }
        while (*p != '\0' && *p != '|') {
            p++;
        }
        if (*p == '\0') {
            return 0;
        }
        p++;
    }
}

static const char *StrStrI(const char *s, const char *pat)
{
    size_t n = strlen(pat);
    for (; *s; s++) {
        if (strnicmp(s, pat, n) == 0) {
            return s;
        }
    }
    return NULL;
}

static int HexVal(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static void HtmlEsc(StrBuf *sb, const char *s)
{
    for (; *s; s++) {
        switch (*s) {
        case '<': SbAdd(sb, "&lt;");   break;
        case '>': SbAdd(sb, "&gt;");   break;
        case '&': SbAdd(sb, "&amp;");  break;
        case '"': SbAdd(sb, "&quot;"); break;
        default:  SbAddC(sb, *s);      break;
        }
    }
}

/* ---------------------------------------------------------------- 文字コード */

static const WCHAR g_cp1252[32] = {
    0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
    0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
    0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
    0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
};

static WCHAR FixWide(unsigned long cp)
{
    if (cp == 0xA0) {
        return NBSP_CH;
    }
    if (cp == 0 || cp == 0x2028 || cp == 0x2029) {
        return ' ';
    }
    if (cp > 0xFFFF) {
        return '?';
    }
    return (WCHAR)cp;
}

static int CodepointToAcp(unsigned long cp, char *out);

/* ANSI の s を UTF-16 に戻すと w と同じになるか (Windows が似た文字で置き換えていないか) */
static int AcpExact(const WCHAR *w, int n, const char *s, int m)
{
    WCHAR  one[4], *b;
    int    k, ok;

    k = MultiByteToWideChar(CP_ACP, 0, s, m, NULL, 0);
    if (k != n) {
        return 0;
    }
    b = n <= 4 ? one : xmalloc((size_t)n * sizeof(WCHAR));
    MultiByteToWideChar(CP_ACP, 0, s, m, b, k);
    ok = memcmp(b, w, (size_t)n * sizeof(WCHAR)) == 0;
    if (b != one) {
        free(b);
    }
    return ok;
}

/* UTF-16 → ANSI。*outLen に長さ */
static char *WideToAcp(const WCHAR *w, int n, long *outLen)
{
    int   m = n ? WideCharToMultiByte(CP_ACP, 0, w, n, NULL, 0, NULL, NULL) : 0;
    char *s = xmalloc(m + 1);
    int   i;
    if (m > 0) {
        m = WideCharToMultiByte(CP_ACP, 0, w, n, s, m, NULL, NULL);
    }
    if (m > 0 && !AcpExact(w, n, s, m)) {
        /* 置き換えられた文字がある: c → c などを避けるため 1 文字ずつ変換し直す */
        free(s);
        s = xmalloc((size_t)n * 4 + 1);         /* 1 文字は最大 3 バイト + 終端 */
        for (i = 0, m = 0; i < n; i++) {
            if (w[i] < 0x80) {
                s[m++] = (char)w[i];
            } else {
                m += CodepointToAcp(w[i], s + m);
            }
        }
    }
    s[m] = '\0';
    *outLen = m;
    return s;
}

/* Win95 の MultiByteToWideChar は CP_UTF8 を扱えないので自前でデコードする */
static char *Utf8ToAcp(const BYTE *s, long len, long *outLen)
{
    WCHAR *w = xmalloc((len + 1) * sizeof(WCHAR));
    long   i = 0;
    int    n = 0;
    char  *r;

    while (i < len) {
        unsigned long c = s[i], cp;
        int           k;
        if (c < 0x80) {
            cp = c; k = 1;
        } else if ((c & 0xE0) == 0xC0 && i + 1 < len && (s[i + 1] & 0xC0) == 0x80) {
            cp = ((c & 0x1F) << 6) | (s[i + 1] & 0x3F); k = 2;
        } else if ((c & 0xF0) == 0xE0 && i + 2 < len && (s[i + 1] & 0xC0) == 0x80
                   && (s[i + 2] & 0xC0) == 0x80) {
            cp = ((c & 0x0F) << 12) | ((s[i + 1] & 0x3FUL) << 6) | (s[i + 2] & 0x3F); k = 3;
        } else if ((c & 0xF8) == 0xF0 && i + 3 < len && (s[i + 1] & 0xC0) == 0x80
                   && (s[i + 2] & 0xC0) == 0x80 && (s[i + 3] & 0xC0) == 0x80) {
            cp = 0x10000; k = 4;
        } else {
            cp = c; k = 1;              /* 不正なバイトは Latin-1 とみなす */
        }
        i += k;
        if (cp != 0xFEFF) {
            w[n++] = FixWide(cp);
        }
    }
    r = WideToAcp(w, n, outLen);
    free(w);
    return r;
}

static char *Latin1ToAcp(const BYTE *s, long len, long *outLen)
{
    WCHAR *w = xmalloc((len + 1) * sizeof(WCHAR));
    long   i;
    char  *r;

    for (i = 0; i < len; i++) {
        w[i] = (s[i] >= 0x80 && s[i] < 0xA0) ? g_cp1252[s[i] - 0x80] : FixWide(s[i]);
    }
    r = WideToAcp(w, (int)len, outLen);
    free(w);
    return r;
}

/* 任意のコードページ → ANSI。変換できなければ NULL */
static char *CpToAcp(UINT cp, const char *s, long len, long *outLen)
{
    int    n = MultiByteToWideChar(cp, 0, s, (int)len, NULL, 0);
    WCHAR *w;
    char  *r;

    if (n <= 0) {
        return NULL;
    }
    w = xmalloc((n + 1) * sizeof(WCHAR));
    n = MultiByteToWideChar(cp, 0, s, (int)len, w, n);
    r = WideToAcp(w, n, outLen);
    free(w);
    return r;
}

static void JisToSjis(int j1, int j2, BYTE *out)
{
    int s1 = ((j1 - 0x21) >> 1) + 0x81;
    int s2;
    if (s1 > 0x9F) {
        s1 += 0x40;
    }
    if (j1 & 1) {
        s2 = j2 + 0x1F;
        if (s2 >= 0x7F) {
            s2++;
        }
    } else {
        s2 = j2 + 0x7E;
    }
    out[0] = (BYTE)s1;
    out[1] = (BYTE)s2;
}

static void SjisToEuc(int s1, int s2, BYTE *out)
{
    int j1, j2;
    if (s1 >= 0xE0) {
        s1 -= 0x40;
    }
    j1 = (s1 - 0x81) * 2 + 0x21;
    if (s2 >= 0x9F) {
        j1++;
        j2 = s2 - 0x7E;
    } else {
        j2 = s2 - 0x1F;
        if (s2 >= 0x80) {
            j2--;
        }
    }
    out[0] = (BYTE)(j1 | 0x80);
    out[1] = (BYTE)(j2 | 0x80);
}

static char *EucToSjis(const BYTE *s, long len, long *outLen)
{
    BYTE *o = xmalloc(len + 1);
    long  i = 0, n = 0;

    while (i < len) {
        BYTE c = s[i];
        if (c == 0x8E && i + 1 < len) {
            o[n++] = s[i + 1]; i += 2;
        } else if (c == 0x8F && i + 2 < len) {
            o[n++] = '?'; i += 3;
        } else if (c >= 0xA1 && c <= 0xFE && i + 1 < len && s[i + 1] >= 0xA1) {
            JisToSjis(c & 0x7F, s[i + 1] & 0x7F, o + n); n += 2; i += 2;
        } else {
            o[n++] = c; i++;
        }
    }
    o[n] = '\0';
    *outLen = n;
    return (char *)o;
}

static char *Iso2022ToSjis(const BYTE *s, long len, long *outLen)
{
    BYTE *o = xmalloc(len + 1);
    long  i = 0, n = 0;
    int   mode = 0;                 /* 0: ASCII / 1: 漢字 / 2: 半角カナ */

    while (i < len) {
        BYTE c = s[i];
        if (c == 0x1B && i + 2 < len) {
            if (s[i + 1] == '$' && (s[i + 2] == 'B' || s[i + 2] == '@')) {
                mode = 1; i += 3; continue;
            }
            if (s[i + 1] == '(') {
                mode = (s[i + 2] == 'I') ? 2 : 0; i += 3; continue;
            }
        }
        if (mode == 1 && c >= 0x21 && c <= 0x7E && i + 1 < len) {
            JisToSjis(c, s[i + 1], o + n); n += 2; i += 2;
        } else if (mode == 2 && c >= 0x21 && c <= 0x5F) {
            o[n++] = (BYTE)(c + 0x80); i++;
        } else {
            o[n++] = c; i++;
        }
    }
    o[n] = '\0';
    *outLen = n;
    return (char *)o;
}

/* Shift_JIS の文字列 (malloc 済み) を ANSI にする。所有権は戻り値へ移る */
static char *SjisToAcp(char *s, long len, long *outLen)
{
    char *r;
    if (GetACP() != 932 && (r = CpToAcp(932, s, len, outLen)) != NULL) {
        free(s);
        return r;
    }
    *outLen = len;
    return s;
}

static int CharsetFromName(const char *p)
{
    char name[32];
    int  n = 0;

    while (*p == ' ' || *p == '"' || *p == '\'') {
        p++;
    }
    while ((isalnum((BYTE)*p) || *p == '-' || *p == '_') && n < 31) {
        name[n++] = (char)tolower((BYTE)*p++);
    }
    name[n] = '\0';
    if (Is(name, "utf-8|utf8")) return CS_UTF8;
    if (Is(name, "shift_jis|shift-jis|sjis|x-sjis|windows-31j|cp932|ms_kanji|csshiftjis")) return CS_SJIS;
    if (Is(name, "euc-jp|x-euc-jp|eucjp|cseucpkdfmtjapanese")) return CS_EUC;
    if (Is(name, "iso-2022-jp|csiso2022jp")) return CS_JIS;
    if (Is(name, "iso-8859-1|latin1|windows-1252|cp1252|us-ascii|ascii|iso-8859-15")) return CS_LATIN1;
    if (Is(name, "x-acp")) return CS_ACP;
    return -1;
}

/* 正しい UTF-8 で、かつ多バイト文字を含むか */
static int LooksUtf8(const BYTE *s, long len)
{
    long i = 0;
    int  multi = 0;

    while (i < len) {
        BYTE c = s[i];
        int  k, j;
        if (c < 0x80) {
            i++;
            continue;
        }
        if ((c & 0xE0) == 0xC0) k = 1;
        else if ((c & 0xF0) == 0xE0) k = 2;
        else if ((c & 0xF8) == 0xF0) k = 3;
        else return 0;
        if (i + k >= len) {
            break;                      /* 末尾で切れているだけなら許す */
        }
        for (j = 1; j <= k; j++) {
            if ((s[i + j] & 0xC0) != 0x80) {
                return 0;
            }
        }
        multi = 1;
        i += k + 1;
    }
    return multi;
}

static int GuessCharset(const BYTE *s, long len)
{
    long i;
    int  sjisLead = 0, high = 0;

    if (LooksUtf8(s, len)) {
        return CS_UTF8;
    }
    for (i = 0; i + 1 < len; i++) {
        if (s[i] == 0x1B && s[i + 1] == '$') {
            return CS_JIS;
        }
        if (s[i] >= 0x80) {
            high = 1;
            if (s[i] >= 0x81 && s[i] <= 0x9F && s[i] != 0x8E && s[i] != 0x8F) {
                sjisLead = 1;
            }
        }
    }
    if (GetACP() == 932 && high) {
        return sjisLead ? CS_SJIS : CS_EUC;
    }
    return CS_ACP;
}

static int DetectCharset(const char *ctype, const char *data, long len, int isHtml)
{
    const char *p;
    int         cs;

    if (ctype != NULL && (p = StrStrI(ctype, "charset=")) != NULL
        && (cs = CharsetFromName(p + 8)) >= 0) {
        return cs;
    }
    if (len >= 3 && (BYTE)data[0] == 0xEF && (BYTE)data[1] == 0xBB && (BYTE)data[2] == 0xBF) {
        return CS_UTF8;
    }
    if (isHtml) {
        /* <meta charset=...> / <meta http-equiv=... content="...; charset=..."> */
        long  n = len < 8192 ? len : 8192;
        char *head = xmalloc(n + 1);
        memcpy(head, data, n);
        head[n] = '\0';
        p = StrStrI(head, "charset=");
        cs = p ? CharsetFromName(p + 8) : -1;
        free(head);
        if (cs >= 0) {
            return cs;
        }
    }
    return GuessCharset((const BYTE *)data, len);
}

/* UTF-8 のスクリプトの写し (NUL 終端。先頭の BOM を除き、途中の NUL は空白にする) */
static char *Utf8Script(const char *data, long len)
{
    char *r;
    long  i;
    if (len >= 3 && (BYTE)data[0] == 0xEF && (BYTE)data[1] == 0xBB && (BYTE)data[2] == 0xBF) {
        data += 3;
        len  -= 3;
    }
    r = xmalloc(len + 1);
    memcpy(r, data, len);
    r[len] = '\0';
    for (i = 0; i < len; i++) {
        if (r[i] == '\0') r[i] = ' ';
    }
    return r;
}

/* 取得データを ANSI の NUL 終端文字列にする */
static char *ConvToAcp(const char *data, long len, int cs)
{
    UINT  acp = GetACP();
    char *r   = NULL;
    long  n   = 0, i;

    switch (cs) {
    case CS_UTF8:
        r = Utf8ToAcp((const BYTE *)data, len, &n);
        break;
    case CS_LATIN1:
        if (acp != 1252) {
            r = Latin1ToAcp((const BYTE *)data, len, &n);
        }
        break;
    case CS_EUC:
        r = EucToSjis((const BYTE *)data, len, &n);
        r = SjisToAcp(r, n, &n);
        break;
    case CS_JIS:
        r = Iso2022ToSjis((const BYTE *)data, len, &n);
        r = SjisToAcp(r, n, &n);
        break;
    case CS_SJIS:
        if (acp != 932) {
            r = CpToAcp(932, data, len, &n);
        }
        break;
    }
    if (r == NULL) {
        r = xmalloc(len + 1);
        memcpy(r, data, len);
        r[len] = '\0';
        n = len;
    }
    for (i = 0; i < n; i++) {
        if (r[i] == '\0') {
            r[i] = ' ';
        }
    }
    return r;
}

static void SbAddUtf8(StrBuf *sb, unsigned cp)
{
    if (cp < 0x80) {
        SbAddC(sb, cp);
    } else if (cp < 0x800) {
        SbAddC(sb, 0xC0 | (cp >> 6));
        SbAddC(sb, 0x80 | (cp & 0x3F));
    } else {
        SbAddC(sb, 0xE0 | (cp >> 12));
        SbAddC(sb, 0x80 | ((cp >> 6) & 0x3F));
        SbAddC(sb, 0x80 | (cp & 0x3F));
    }
}

/* ANSI 文字列を文字コード cs のバイト列にする (フォーム送信用) */
static void AcpToCharset(StrBuf *out, const char *s, int cs)
{
    int n;

    if (cs == CS_UTF8 && (n = MultiByteToWideChar(CP_ACP, 0, s, -1, NULL, 0)) > 0) {
        WCHAR *w = xmalloc(n * sizeof(WCHAR));
        int    i;
        MultiByteToWideChar(CP_ACP, 0, s, -1, w, n);
        for (i = 0; i < n - 1; i++) {
            SbAddUtf8(out, w[i]);
        }
        free(w);
        return;
    }
    if (cs == CS_EUC && GetACP() == 932) {
        const BYTE *p = (const BYTE *)s;
        while (*p) {
            BYTE e[2];
            if (IsDBCSLeadByte(*p) && p[1]) {
                SjisToEuc(p[0], p[1], e);
                SbAddN(out, (char *)e, 2);
                p += 2;
            } else if (*p >= 0xA1 && *p <= 0xDF) {
                SbAddC(out, 0x8E);
                SbAddC(out, *p++);
            } else {
                SbAddC(out, *p++);
            }
        }
        return;
    }
    SbAdd(out, s);
}

/* application/x-www-form-urlencoded 形式で追加 */
static void SbAddUrlEnc(StrBuf *sb, const char *s, int cs)
{
    static const char hex[] = "0123456789ABCDEF";
    StrBuf raw = { 0 };
    int    i;

    AcpToCharset(&raw, s, cs);
    for (i = 0; i < raw.len; i++) {
        BYTE c = (BYTE)raw.p[i];
        if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~' || c == '*') {
            SbAddC(sb, c);
        } else if (c == ' ') {
            SbAddC(sb, '+');
        } else {
            SbAddC(sb, '%');
            SbAddC(sb, hex[c >> 4]);
            SbAddC(sb, hex[c & 15]);
        }
    }
    free(raw.p);
}

